def bound_region_leaf(entry: RegionBatchEntry) -> bytes:
    items = [b"zkregion/region-bound/v1"]
    for commitment in (entry.x_commitment, entry.y_commitment):
        items += [
            str(value).encode("ascii")
            for value in (
                commitment.element,
                commitment.lower,
                commitment.upper,
                commitment.prime,
                commitment.generator,
                commitment.h,
